<template><PageShell :title="config.title" :subtitle="config.subtitle" :icon="config.icon" eyebrow="Platform Executive"><section class="overflow-hidden rounded-3xl border border-base-300 bg-base-100 shadow-sm dark:border-white/10 dark:bg-[#071829]"><div v-if="loading" class="py-20 text-center text-sm text-slate-400">Loading records...</div><div v-else-if="!items.length" class="py-20 text-center"><Icon :icon="config.icon" width="30" class="mx-auto text-slate-300"/><p class="mt-3 font-black text-slate-700 dark:text-white/70">{{ config.empty }}</p><p class="mt-1 text-xs text-slate-400">This page shows real request statuses only; no review case is fabricated.</p></div><div v-else class="divide-y divide-base-300 dark:divide-white/5"><article v-for="i in items" :key="i.id" class="p-5"><div class="flex flex-wrap justify-between gap-3"><div><p class="font-black text-slate-800 dark:text-white/75">{{ i.reference_number }} · {{ i.category_name }}</p><p class="mt-1 text-xs text-slate-400">{{ i.requester_name||'Guest requester' }} · {{ i.address_text }}</p></div><span class="h-fit rounded-full px-2.5 py-1 text-[.65rem] font-black" :class="mode==='false_alarm'?'bg-red-100 text-red-700':'bg-amber-100 text-amber-700'">{{ i.status }}</span></div><p v-if="closure(i).note" class="mt-3 rounded-xl bg-base-200/60 px-3 py-2 text-xs leading-5 text-slate-600 dark:bg-white/5 dark:text-white/60">{{ closure(i).note }}</p><p class="mt-3 text-xs text-slate-500">Submitted {{ format(i.submitted_at) }}<template v-if="closure(i).at"> · Closed {{ format(closure(i).at) }}</template></p></article></div></section></PageShell></template>
<script setup>import{computed,onMounted,ref,watch}from'vue';import{useRoute}from'vue-router';import{Icon}from'@iconify/vue';import PageShell from '@/components/management/PageShell.vue';import{fetchPlatformIncidents}from'@/services/dispatchOperations';const route=useRoute(),items=ref([]),loading=ref(false),mode=computed(()=>route.meta.reviewMode||'cancelled'),configs={cancelled:{title:'Cancellations & Complaints',subtitle:'Emergency requests cancelled by their requester, the handling organization, or platform oversight — with who closed each one and why.',icon:'lucide:message-square-warning',empty:'No cancelled requests are currently recorded.'},false_alarm:{title:'False Alarm Review',subtitle:'Requests the handling organization or platform oversight marked as false alarms, with the reason recorded at closing.',icon:'lucide:shield-alert',empty:'No false-alarm requests are currently recorded.'}},config=computed(()=>configs[mode.value]);const closure=i=>{const [at,...rest]=String(i.last_status_entry||'').split('|');return{at:at||null,note:rest.join('|')}};const format=v=>v?new Date(String(v).replace(' ','T')).toLocaleString():'—';async function load(){loading.value=true;try{const d=await fetchPlatformIncidents({status:mode.value==='false_alarm'?'false_alarm':'cancelled',per_page:50});items.value=d.items||[]}finally{loading.value=false}};watch(mode,load);onMounted(load)</script>
